// 8.3.0 (#99): the secret-like path check also runs at plan time, before plan-audit.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { ARGS, SRC_PATH, happy, run } from "./harness.mjs";

// the dist is regenerated by the main thread; these tests run the source
const SRC = readFileSync(SRC_PATH, "utf8");
const mk = () => Object.assign(happy(), { __source: SRC });

const withFiles = (s, files) => Object.assign(s["role:scope-and-plan"], { allowed_additions: { files, symbols: [], deps: [], settings: [] } });
// 8.3.1 (#99 a): a source file named secrets.py is no longer secret-like; a secrets.yaml still is
const SECRET = "packages/core/src/output_scan/secrets.yaml";

test("8.3.0 (#99): a secret-like planned path stops before plan-audit", async () => {
  const s = mk();
  withFiles(s, [SECRET]);
  const out = await run(s, ARGS);
  assert.equal(out.result.status, "needs_human");
  assert.equal(out.result.stop_gate, "scope");
  assert.match(out.result.reason, /scope check failed: path "packages\/core\/src\/output_scan\/secrets\.yaml": secret-like path/);
  assert.ok(!out.labels.some((l) => l.startsWith("role:plan-audit")), "plan-audit never ran");
});

test("8.3.0 (#99): a clean plan reaches plan-audit", async () => {
  const s = mk();
  withFiles(s, ["src/detectors.py"]);
  const out = await run(s, ARGS);
  assert.ok(out.labels.some((l) => l.startsWith("role:plan-audit")));
});

test("8.3.0 (#99): the auto-confirm scope check still uses the secret-like fence", async () => {
  const { readFileSync } = await import("node:fs");
  const src = readFileSync(new URL("../src/build-engine.js", import.meta.url), "utf8");
  assert.match(src, /const g3 = scopeProblems\(ctx\);\n\s+if \(g3\.length\) return fail\("scope", g3\)/);
  assert.match(src, /out\.push\(\.\.\.pathFenceProblems\(paths\)\)/);
});
